<?php get_header(); ?><article class="or-article"><div class="or-container"><header class="or-article-header"><?php or_breadcrumbs(); ?><p class="or-eyebrow">Comparativo</p><h1><?php the_title(); ?></h1><p class="or-article-lead"><?php echo esc_html(get_the_excerpt()); ?></p><?php if(has_post_thumbnail()): ?><div class="or-featured"><?php the_post_thumbnail('full',array('loading'=>'eager')); ?></div><?php endif; ?></header><div class="or-content"><section><h2>Ranking</h2><?php the_content(); ?></section><?php $table=or_meta('or_comparison_table'); if($table): ?><section><h2>Comparação lado a lado</h2><div class="or-table-wrap"><?php echo wp_kses_post($table); ?></div></section><?php endif; ?><?php foreach(array('or_editor_choice'=>'🏆 Escolha do editor','or_best_value'=>'💰 Melhor custo-benefício') as $key=>$label): if($value=or_meta($key)): ?><section class="or-summary"><strong><?php echo esc_html($label); ?></strong><p><?php echo esc_html($value); ?></p></section><?php endif; endforeach; ?><?php $affiliate=or_meta('or_affiliate_url'); if($affiliate): ?><p><a class="or-btn or-btn-primary" href="<?php echo or_affiliate_url($affiliate); ?>" rel="sponsored noopener noreferrer" target="_blank">Ver preço atualizado</a></p><?php endif; ?></div></div></article><?php get_footer(); ?>
